#include <Stepper.h>

const int STEPS_PER_REV = 2048;
Stepper myStepper(STEPS_PER_REV, 8, 10, 9, 11);
const int DC_PWM_PIN = 5;
const int DC_DIR_PIN = 4;

void setup() {
  myStepper.setSpeed(10);
  pinMode(DC_PWM_PIN, OUTPUT);
  pinMode(DC_DIR_PIN, OUTPUT);
}

void loop() {
  int joyX = analogRead(A0);
  int joyY = analogRead(A1);

  // Stepper positioning via X-axis
  if (joyX > 600) myStepper.step(20);
  else if (joyX < 400) myStepper.step(-20);

  // DC motor throttle via Y-axis
  int speed = map(abs(joyY - 512), 50, 512, 0, 255);
  speed = constrain(speed, 0, 255);
  digitalWrite(DC_DIR_PIN, joyY > 512 ? HIGH : LOW);
  analogWrite(DC_PWM_PIN, speed);
}
